head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > M > setCustomFormatter]<br/>Body Column 정보를 사용하여 특정 Column 의 customFormatter 속성을 설정합니다.",
    "validation" : [
        "columnInfo(필수) 파라미터로 customFormatter 속성을 설정할 Body Cell 의 Column ID 를 설정할 수 있어야 합니다.",
    ]
}



// ★ formatter(사용자 함수) 1 : formattedData(포맷 적용 데이터)를 그대로 활용하여 접미사 부착
scwin.fmtWon = function (data, formattedData, rowIndex, columnIndex) {
    return formattedData + " won";
};

// ★ formatter(사용자 함수) 2 : 파라미터 4종(data/formattedData/rowIndex/columnIndex) 전달 + this=GridView
scwin.fmtFull = function (data, formattedData, rowIndex, columnIndex) {
    return "[R" + rowIndex + " C" + columnIndex + "] d=" + data + " f=" + formattedData + " this.getRowCount()=" + this.getRowCount();
};



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);

    // 초기 파라미터 선택값
    par_columnInfo.setValue("ctext");
    par_formatter.setValue("scwin.fmtWon");
};



// comp 생성 : 본 샘플은 columnInfo 를 Column ID 로 지정하는 분리 케이스.
//  allow-list inputType(동작) 과 대조용 inputType(미동작) Column 을 함께 구성한다.
//  Column ID : ctext text(displayFormat) / clink link / cselect select / cauto autoComplete /
//              ctextarea textarea / cexpr expression / ctextimg textImage (여기까지 allow-list, 동작) /
//              ccheck checkbox / ccal calendar (대조용, 미동작)
scwin.comp_init = async function () {
    // 기존 target/dataList 있으면 삭제
    if (typeof dlt_grade !== 'undefined') {
        $p.data.remove("dlt_grade");
    }
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // 컬럼 구성 안내 라벨 (target 생성 전 가장 먼저 생성)
    $c.gcm.createLabel('label="[전제] Body Column ID - ctext:text(displayFormat=#,##0) / clink:link / cselect:select / cauto:autoComplete / ctextarea:textarea / cexpr:expression / ctextimg:textImage (여기까지 allow-list, 동작) / ccheck:checkbox / ccal:calendar (대조용, 미동작). 데이터 Row 3개.\n[절차] columnInfo 를 Column ID 문자열로 지정하고 formatter(함수명) 선택 후 (setCustomFormatter 실행) -> 해당 Column 모든 Row 셀의 화면 표시값이 사용자 함수 반환값으로 바뀌는지 확인.\n[확인] allow-list Column ID 는 반환값으로 변경되고, checkbox/calendar 는 미변경(미동작). columnInfo 를 인덱스로 지정하는 검증은 _1 샘플에서 다룬다."', '', 'label1');

    // select / autoComplete Column 의 itemset 용 DataList (코드/라벨)
    let strGrade = '';
    strGrade += '<w2:dataList ' + $c.gcm.getNameSpace() + ' id="dlt_grade" baseNode="list" repeatNode="map">';
    strGrade += '<w2:columnInfo>';
    strGrade += '<w2:column id="code" name="code" dataType="text"></w2:column>';
    strGrade += '<w2:column id="label" name="label" dataType="text"></w2:column>';
    strGrade += '</w2:columnInfo>';
    strGrade += '<w2:data use="true"></w2:data>';
    strGrade += '</w2:dataList>';
    $p.data.create(strGrade);
    dlt_grade.setJSON([
        { "code": "A", "label": "최우수" },
        { "code": "B", "label": "우수" },
        { "code": "C", "label": "보통" }
    ], false);

    // 실제 서빙되는 아이콘 이미지 (textImage 가 화면에 보이도록)
    let imgSrc = "/cm/images/contents/btn_folder.png";

    // GridView 와 바인딩할 DataList 동적 생성
    let strDlt = '';
    strDlt += '<w2:dataList ' + $c.gcm.getNameSpace() + ' id="dlt_bind" baseNode="list" repeatNode="map">';
    strDlt += '<w2:columnInfo>';
    strDlt += '<w2:column id="ctext" name="ctext" dataType="number"></w2:column>';
    strDlt += '<w2:column id="clink" name="clink" dataType="text"></w2:column>';
    strDlt += '<w2:column id="cselect" name="cselect" dataType="text"></w2:column>';
    strDlt += '<w2:column id="cauto" name="cauto" dataType="text"></w2:column>';
    strDlt += '<w2:column id="ctextarea" name="ctextarea" dataType="text"></w2:column>';
    strDlt += '<w2:column id="csrc" name="csrc" dataType="number"></w2:column>';
    strDlt += '<w2:column id="ctextimg" name="ctextimg" dataType="text"></w2:column>';
    strDlt += '<w2:column id="ccheck" name="ccheck" dataType="text"></w2:column>';
    strDlt += '<w2:column id="ccal" name="ccal" dataType="text"></w2:column>';
    strDlt += '</w2:columnInfo>';
    strDlt += '<w2:data use="true"></w2:data>';
    strDlt += '</w2:dataList>';
    $p.data.create(strDlt);

    let jsonData = [
        { "ctext": "1250",  "clink": "상세보기", "cselect": "A", "cauto": "A", "ctextarea": "재고확인\n2층 보관", "csrc": "5",  "ctextimg": "정상", "ccheck": "Y", "ccal": "20250115" },
        { "ctext": "30500", "clink": "상세보기", "cselect": "B", "cauto": "B", "ctextarea": "신규입고\n검수 대기", "csrc": "10", "ctextimg": "지연", "ccheck": "N", "ccal": "20250220" },
        { "ctext": "780",   "clink": "상세보기", "cselect": "C", "cauto": "C", "ctextarea": "할인적용\n20% 할인", "csrc": "15", "ctextimg": "정상", "ccheck": "Y", "ccal": "20250312" }
    ];
    dlt_bind.setJSON(jsonData, false);

    // Property 설정은 createCList 공통 함수 사용
    let properties = {
        dataList: "data:dlt_bind",
    };
    let cList = $c.gcm.createCList(properties);

    let grp_comp = $c.gcm.getTestGroup();
    let strNameSpace = $c.gcm.getNameSpace();

    // itemset 공통 조각 (select / autoComplete 용)
    let itemset = '<w2:choices><w2:itemset nodeset="data:dlt_grade"><w2:label ref="label"></w2:label><w2:value ref="code"></w2:value></w2:itemset></w2:choices>';

    // target 생성
    let strTarget = '';
    strTarget += '<w2:gridView ' + strNameSpace + ' ' + cList + ' id="" style="width:100%;height:220px;">';
    strTarget += '<w2:caption style="" id="caption1" value="setCustomFormatter 테스트 그리드 (ID)"></w2:caption>';
    strTarget += '<w2:header style="" id="header1"><w2:row style="" id="hrow1">';
    strTarget += '<w2:column width="150" inputType="text" id="h0" value="ctext:text(displayFormat)"></w2:column>';
    strTarget += '<w2:column width="90" inputType="text" id="h2" value="clink:link"></w2:column>';
    strTarget += '<w2:column width="90" inputType="text" id="h3" value="cselect:select"></w2:column>';
    strTarget += '<w2:column width="110" inputType="text" id="h4" value="cauto:autoComplete"></w2:column>';
    strTarget += '<w2:column width="120" inputType="text" id="h5" value="ctextarea:textarea"></w2:column>';
    strTarget += '<w2:column width="100" inputType="text" id="h6" value="cexpr:expression"></w2:column>';
    strTarget += '<w2:column width="100" inputType="text" id="h7" value="ctextimg:textImage"></w2:column>';
    strTarget += '<w2:column width="80" inputType="text" id="h8" value="ccheck:checkbox(대조)"></w2:column>';
    strTarget += '<w2:column width="90" inputType="text" id="h9" value="ccal:calendar(대조)"></w2:column>';
    strTarget += '<w2:column width="*" inputType="text" id="h10" value="csrc:text(number)"></w2:column>';
    strTarget += '</w2:row></w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1"><w2:row style="" id="brow1">';
    //  (중요) body 컬럼 id 는 dataList 컬럼 id 와 동일해야 셀에 데이터가 바인딩됨
    // ctext : text + displayFormat="#,##0" (allow) -> formatter 의 formattedData 가 콤마 포맷값 전달
    strTarget += '<w2:column width="150" inputType="text" dataType="number" displayFormat="#,##0" id="ctext" dataList="ctext"></w2:column>';
    // clink : link (allow)
    strTarget += '<w2:column width="90" inputType="link" id="clink" dataList="clink"></w2:column>';
    // cselect : select (allow)
    strTarget += '<w2:column width="90" inputType="select" id="cselect" dataList="cselect">' + itemset + '</w2:column>';
    // cauto : autoComplete (allow)
    strTarget += '<w2:column width="110" inputType="autoComplete" id="cauto" dataList="cauto">' + itemset + '</w2:column>';
    // ctextarea : textarea (allow)
    strTarget += '<w2:column width="120" inputType="textarea" id="ctextarea" dataList="ctextarea"></w2:column>';
    // cexpr : expression (allow) -> csrc x 10 계산값 표시
    strTarget += '<w2:column width="100" inputType="expression" id="cexpr" displayFormat="#,###" expression="Number(display(\'csrc\'))*10"></w2:column>';
    // ctextimg : textImage (allow)
    strTarget += '<w2:column width="100" inputType="textImage" id="ctextimg" dataList="ctextimg" viewType="icon" imageSrc="' + imgSrc + '"></w2:column>';
    // ccheck : checkbox (대조용, allow-list 밖 -> customFormatter 미동작)
    strTarget += '<w2:column width="80" inputType="checkbox" id="ccheck" dataList="ccheck" trueValue="Y" falseValue="N"></w2:column>';
    // ccal : calendar (대조용, allow-list 밖 -> customFormatter 미동작)
    strTarget += '<w2:column width="90" inputType="calendar" id="ccal" dataList="ccal"></w2:column>';
    // csrc : text(number) (allow) -> expression(cexpr) 의 원본값 제공(display(\'csrc\')) 겸 allow-list 검증용
    strTarget += '<w2:column width="*" inputType="text" dataType="number" id="csrc" dataList="csrc"></w2:column>';
    strTarget += '</w2:row></w2:gBody>';
    strTarget += '</w2:gridView>';

    scwin.target1 = await $p.dynamicCreate(
        "target1",
        "gridView",
        strTarget,
        grp_comp
    );
}



// [실행] setCustomFormatter : columnInfo 를 Column ID(문자열) 로 지정하여 해당 Column 의 customFormatter 속성을 설정한다.
//  - 설정 후 해당 Column 의 모든 Row 화면 표시값(td.textContent) 을 수집하여 사용자 함수 반환값으로 변환/재렌더되었는지 확인
//  - allow-list Column ID 는 변경되고, checkbox/calendar 대조 Column ID 는 미변경(미동작)
scwin.btn_setCustomFormatter_onclick = function () {
    let colID = par_columnInfo.getValue();
    let formatter = par_formatter.getValue();
    // Column ID 로부터 인덱스 산출 (셀 td 조회용)
    let columnIndex = target1.getColumnIndex(colID);
    let cnt = dlt_bind.getRowCount();

    // setCustomFormatter 호출 (columnInfo 를 Column ID 로 지정)
    target1.setCustomFormatter(colID, formatter);

    // 적용된 해당 Column 의 모든 Row 화면 표시값 수집
    let arr = [];
    for (let r = 0; r < cnt; r++) {
        let td = document.querySelector("td[id*='target1_cell_" + r + "_" + columnIndex + "']");
        arr.push(td ? td.textContent.trim() : '(td없음)');
    }

    wf_body_bottom.getObj("scwin").setReturnValue(
        "setCustomFormatter('" + colID + "', '" + formatter + "') [colIndex=" + columnIndex + "] -> 모든 Row 화면 표시값 : " + arr.join(' | '));
}
